<?php
require_once ROOT.'/src/explore.php';require_once ROOT.'/src/explore-trips.php';require_once ROOT.'/views/network-components.php';
$f=[];foreach(['q','city','country','category','cost','tab','sort','view','trip','max_minutes','max_stops','max_walking'] as $key)$f[$key]=is_string($_GET[$key]??null)?mb_substr($_GET[$key],0,120):'';
if(!preg_match('/^[a-f0-9]{32}$/D',$f['trip']))$f['trip']='';
if(!$f['city']&&is_string($_GET['destination']??null))$f['city']=$_GET['destination'];
if(!in_array($f['tab'],['places','activities','trips'],true))$f['tab']='all';
$f['view']=$f['view']==='map'?'map':'list';$f['sort']=in_array($f['sort'],['newest','rating'],true)?$f['sort']:'relevance';
$shareMatches=in_array($f['tab'],['all','trips'],true)?exTripRows($f):[];$rows=$f['tab']==='trips'?[]:exFilter(exCatalogue(),$f);$page=max(1,(int)($_GET['page']??1));$perPage=12;
$groups=[];$pages=max(1,(int)ceil(count($shareMatches)/$perPage));foreach(['places','activities'] as $group){$matches=array_values(array_filter($rows,fn($r)=>$r['entity']===$group));$pages=max($pages,(int)ceil(count($matches)/$perPage));$groups[$group]=['count'=>count($matches),'rows'=>array_slice($matches,($page-1)*$perPage,$perPage)];}
$title=exT('explore');$destinations=tripDestinations();$cityLabel=isset($destinations[$f['city']])?(destinationCityNames($destinations[$f['city']])[siteLanguage()]??destinationCityNames($destinations[$f['city']])['en']):'';
$u=socialUser();$mapRows=[];if($f['view']==='map')foreach($rows as $mapItem){$mapLocation=rxLocation($mapItem);if($mapLocation['coords']??null)$mapRows[]=['id'=>$mapItem['id'],'title'=>$mapItem['title'],'coords'=>$mapLocation['coords'],'url'=>$mapItem['url']];}if($f['view']==='map')foreach($shareMatches as $tripRow)if($tripRow['coords'])$mapRows[]=$tripRow;$nav=[['home','home','/community/'],['place','discover','/explore/'],['map','my_trips','/my-trip/'],['heart','saved','/community/saved/'],['user','profile',$u?'/community/members/'.$u['handle'].'/':'/community/account/']];
?>
