<section class="ex-main" data-explore data-labels="<?=e(json_encode(exLabels()+['map_error'=>rxT('map_error'),'start'=>json_decode(file_get_contents(ROOT.'/content/trip-map-labels.json'),true)[siteLanguage()]['start'],'stops'=>tsT('stops')],JSON_UNESCAPED_UNICODE))?>">
<form method="get" class="ex-filters"><input type="hidden" name="lang" value="<?=e(siteLanguage())?>"><input type="hidden" name="tab" value="<?=e($f['tab'])?>"><input type="hidden" name="view" value="<?=e($f['view'])?>">
<div class="ex-heading"><div><h1><?=e($title.($cityLabel?' · '.$cityLabel:''))?></h1><p><?=e(exT('subtitle'))?></p></div><div class="ex-heading-controls"><?php foreach(['list','map'] as $view):?><a class="button secondary" href="<?=e(exUrl($f,['view'=>$view]))?>" <?=$f['view']===$view?'aria-current="page"':''?>><?=e(exT($view))?></a><?php endforeach?></div></div>
<div class="ex-search"><label class="sr-only" for="explore-search"><?=e(exT('search'))?></label><input id="explore-search" type="search" name="q" value="<?=e($f['q'])?>" placeholder="<?=e(exT('search'))?>"><button class="button"><?=e(exT('search'))?></button></div>
<nav class="ex-tabs"><?php foreach(['all','places','activities','trips'] as $tab):?><a href="<?=e(exUrl($f,['tab'=>$tab]))?>" <?=$f['tab']===$tab?'aria-current="page"':''?>><?=e($tab==='trips'?tsT('public_trips'):exT($tab))?></a><?php endforeach?></nav>
<div class="ex-filter-row"><?php networkDestinationPicker($f['country'],$f['city'],exUrl($f));?><label><?=e(exT('category'))?><select name="category"><option value=""><?=e(exT('all'))?></option><?php foreach(discoveryTaxonomy() as $key=>$category):?><option value="<?=e($key)?>" <?=$f['category']===$key?'selected':''?>><?=e(exT('category_'.$key))?></option><?php endforeach?></select></label><label><?=e(exT('cost'))?><select name="cost"><option value=""><?=e(exT('all'))?></option><?php foreach(['free','paid','unknown'] as $cost):?><option value="<?=$cost?>" <?=$f['cost']===$cost?'selected':''?>><?=e(exT($cost))?></option><?php endforeach?></select></label><label class="ex-sort"><?=e(exT('sort'))?><select name="sort"><?php foreach(['relevance','newest','rating'] as $sort):?><option value="<?=$sort?>" <?=$f['sort']===$sort?'selected':''?>><?=e(exT($sort))?></option><?php endforeach?></select></label><button class="button secondary"><?=e(exT('filters'))?></button><a href="<?=e(languageUrl('/explore/',siteLanguage()))?>"><?=e(exT('reset'))?></a></div>
<?php if(tdEnabled()):?><fieldset class="td-discovery-facts"><legend><?=e(tsT('public_trips'))?></legend><?php foreach(['max_minutes'=>120,'max_stops'=>3,'max_walking'=>2000] as $key=>$limit):?><label><input type="checkbox" name="<?=e($key)?>" value="<?=$limit?>" <?=!empty($f[$key])?'checked':''?>><?=e(str_replace('{distance}',rxDistance(2000),tdLabels()[$key]))?></label><?php endforeach?><button class="button secondary"><?=e(exT('filters'))?></button><a href="<?=e(exUrl($f,['max_minutes'=>'','max_stops'=>'','max_walking'=>'']))?>"><?=e(tdLabels()['clear'])?></a></fieldset><?php endif?>
</form>
<p class="ex-status" role="status"><?=e($networkError?:$networkMessage)?></p><p class="ex-count"><?=count($rows)+count($shareMatches)?> <?=e(exT('results'))?></p>
