<?php if(!$rows&&!$shareMatches):?><p class="ex-empty"><?=e(exT('no_results'))?></p><?php endif?>
<?php foreach($groups as $group=>$data):if(!$data['count'])continue;?><section class="ex-section"><header><h2><?=e(exT($group))?> <small>(<?=$data['count']?>)</small></h2><?php if($f['tab']==='all'):?><a href="<?=e(exUrl($f,['tab'=>$group]))?>"><?=e(exT('all'))?> →</a><?php endif?></header>
<?php if($group==='activities'):?><p class="ex-disclosure"><?=e(exT('booking_note'))?></p><?php endif?>
<div class="ex-grid ex-<?=$group?>"><?php foreach($data['rows'] as $item):?>
<article class="ex-card <?=empty($item['image'])?'ex-no-image':''?>" data-place-id="<?=e($item['id'])?>">
<?php if(!empty($item['image'])):?><div class="ex-photo"><a href="<?=e($item['url'])?>"><img src="<?=e($item['image'])?>" alt="" loading="lazy" width="240" height="180"></a><details class="ex-image-details"><summary><?=e(plcT('image_details'))?></summary><small><?=e(implode(' · ',array_filter([$item['credit']??'',...array_values(array_intersect_key($item['image_disclosure']??[],array_flip(['photo_author','photo_source','photo_license'])))])))?></small></details><?php if(!empty($item['photo_illustration']))echo photoAiBadge();?></div><?php else:?><span class="ex-placeholder" aria-hidden="true"><?=scIcon('place')?></span><?php endif?>
<div class="ex-card-body"><div class="ex-card-title"><h3><a href="<?=e($item['url'])?>" dir="auto"><?=e($item['title'])?></a></h3><?php networkButton('save','catalog',$item['id'],exT('save'));?></div>
<?php if($group==='places')exRating($item);?>
<p class="ex-location"><?=e($item['city_label']?:exT('location_missing'))?></p>
<?php if($group==='places'):?><span class="ex-cost ex-cost-<?=e($item['cost'])?>"><?=e(exT($item['cost']))?></span><p class="ex-source"><?=scIcon(!empty($item['community'])?'user':'story')?><span><?=e(exT(!empty($item['community'])?'community':'library'))?><?php if(!empty($item['community'])&&!empty($item['contributor'])):?> · <a class="ex-contributor" href="<?=e($item['contributor']['url'])?>"><?=networkAvatar($item['contributor'],'ex-contributor-avatar')?><bdi><?=e($item['contributor']['name'])?></bdi></a><?php endif?></span></p><?php else:?><p class="ex-description" dir="auto"><?=e($item['summary']??'')?></p><p class="ex-provider"><?=e($item['offer']['provider']??uxT('booking_unavailable'))?></p><?php if(!empty($item['price'])):?><p><?=e(str_replace('{price}',$item['price'],exT('price_from')))?></p><?php endif?><?php endif?>
<div class="ex-actions"><?php if($group==='places'):?><?=rxDirections($item)?><button type="button" class="button" data-ex-add="<?=e(json_encode(['id'=>$item['id'],'title'=>$item['title'],'city'=>$item['city']??'','type'=>'place'],JSON_UNESCAPED_UNICODE))?>">＋ <?=e(exT('add'))?></button><a class="button secondary" href="<?=e($item['url'])?>"><?=e(exT('view'))?> →</a><?php else:if($item['offer']):?><a class="button" href="<?=e($item['offer']['url'])?>"><?=e(exT('availability'))?> →</a><small class="ex-disclosure"><?=e(exT('booking_note'))?></small><?php endif?><a href="<?=e($item['url'])?>"><?=e(exT('details'))?></a><?php endif?></div></div></article>
<?php endforeach?></div></section><?php endforeach?>
<?php if($pages>1):?><nav class="ex-pagination"><?php if($page>1):?><a class="button secondary" href="<?=e(exUrl($f,['page'=>$page-1]))?>"><?=e(exT('previous'))?></a><?php endif?><span><?=$page?> / <?=$pages?></span><?php if($page<$pages):?><a class="button secondary" href="<?=e(exUrl($f,['page'=>$page+1]))?>"><?=e(exT('next'))?></a><?php endif?></nav><?php endif?>
<script type="application/json" id="explore-map-data"><?=json_encode($mapRows,JSON_HEX_TAG|JSON_HEX_AMP)?></script>
<?php if($shareMatches):?><section class="ts-profile"><h2><?=e(tsT('public_trips'))?></h2><?php foreach(array_slice($shareMatches,($page-1)*$perPage,$perPage) as $tripRow):?><a class="ts-card" href="<?=e($tripRow['url'])?>"><?php if($tripRow['image']):?><img src="<?=e($tripRow['image'])?>" alt="" loading="lazy"><?php endif?><strong dir="auto"><?=e($tripRow['title'])?></strong><small><?=e($tripRow['destination'])?></small><small><?=$tripRow['stops']?> <?=e(tsT('stops'))?> · <?=e($tripRow['details'])?></small><?php if(!$tripRow['coords']):?><small><?=e(tsT('location_missing'))?></small><?php endif?></a><?php endforeach?></section><?php endif?>
